8	// This file holds the label rules shared by the two ways a release
9	// configuration can be validated: parsing a JSON document (ParseReleaseInput)
10	// and validating a directly constructed Go config (ValidateReleaseInput).
11	//
12	// The rules themselves: label keys must be non-empty; label values are matched
13	// exactly as written — an empty string is a valid value and is never trimmed,
14	// dropped, or case-folded; a condition object must hold at least one entry.
15	// When one label set or condition has several problems, the first one in
16	// ascending key order is reported, so repeated calls give the same error.
17	// Each path keeps its own error wording (cluster identity vs. list position)
18	// by formatting errors at the call site.
19	
20	// sortedLabelKeys returns the keys of a label set in ascending order, so both
21	// validation paths examine keys — and therefore report problems — in the same
22	// deterministic order.
23	func sortedLabelKeys[V any](labels map[string]V) []string {
24		keys := make([]string, 0, len(labels))
25		for k := range labels {
26			keys = append(keys, k)
27		}
28		sort.Strings(keys)
29		return keys
30	}
31	
32	// hasEmptyLabelKey reports whether the label set contains an empty key. An
33	// empty key sorts before any other key, so it is always the first problem
34	// found when keys are examined in ascending order.
35	func hasEmptyLabelKey[V any](labels map[string]V) bool {
36		for _, k := range sortedLabelKeys(labels) {
37			if k == "" {
38				return true
39			}
40		}
41		return false
42	}
43	
44	// validateCondition enforces the shared rules for one include/exclude
45	// condition: it must contain at least one entry and no empty label keys. The
46	// error names the field ("include" or "exclude") and the condition's position,
47	// the wording both the JSON and the Go-config paths already use.
48	func validateCondition(field string, index int, cond LabelCondition) error {
49		if len(cond) == 0 {
50			return fmt.Errorf("%s[%d] 不能为空条件对象", field, index)
51		}
52		if hasEmptyLabelKey(cond) {
53			return fmt.Errorf("%s[%d] 的标签键不能为空", field, index)
54		}
55		return nil
56	}
57	
58	// labelsFromJSON validates a decoded JSON object against the shared label
59	// rules and returns it as a label set: keys must be non-empty and every value
60	// must be a string, preserved exactly as written. Keys are examined in
61	// ascending order and the first problem is reported through keyErr (empty key)
62	// or valueErr (non-string value), which format the error for the caller's
63	// context — cluster tags or an include/exclude condition.
64	func labelsFromJSON(obj map[string]any, keyErr, valueErr func(key string) error) (map[string]string, error) {
65		labels := make(map[string]string, len(obj))
