1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"sort"
10		"strings"
11	)
12	
13	// Reason constants for clusters that cannot enter a release plan.
14	const (
15		ReasonDisabled          = "集群已停用"
16		ReasonExcludeMatched    = "命中排除条件"
17		ReasonIncludeNotMatched = "未命中包含条件"
18	)
19	
20	// LabelCondition is a set of exact key-value matches; all must match.
21	type LabelCondition map[string]string
22	
23	// Cluster is a candidate target for a release.
24	type Cluster struct {
25		ID       string
26		Disabled bool
27		Tags     map[string]string
28	}
29	
30	// ReleasePlanInput describes an application release to plan offline.
31	type ReleasePlanInput struct {
32		App       string
33		Revision  string
34		Image     string
35		BatchSize int
36		Clusters  []Cluster
37		Include   []LabelCondition
38		Exclude   []LabelCondition
39		// SpreadBy, when non-empty, names a cluster tag whose value identifies a
40		// fault domain; each batch then contains at most one cluster per domain.
41		SpreadBy string
42	}
43	
44	// AppInfo identifies the application being released.
45	type AppInfo struct {
46		Name     string `json:"name"`
47		Revision string `json:"revision"`
48		Image    string `json:"image"`
49	}
50	
51	// Batch is a sequentially numbered group of cluster IDs.
52	type Batch struct {
53		Index    int      `json:"index"`
54		Clusters []string `json:"clusters"`
55	}
56	
57	// ExcludedCluster explains why a cluster is not in the plan.
58	type ExcludedCluster struct {
59		ID     string `json:"id"`
60		Reason string `json:"reason"`
61	}
62	
63	// ReleasePlan is the deterministic offline release plan.
64	type ReleasePlan struct {
65		App      AppInfo           `json:"app"`
66		Batches  []Batch           `json:"batches"`
67		Excluded []ExcludedCluster `json:"excluded"`
68	}
69	
70	// ParseReleaseInput reads a release plan document and validates its fields.
71	// Every JSON object in the document — including unknown fields and their
72	// nested objects — must have distinct member names; a name appearing twice
73	// (even with the same value, or via equivalent Unicode escapes) is rejected
74	// before any business validation runs.
75	func ParseReleaseInput(data []byte) (ReleasePlanInput, error) {
76		if err := checkDuplicateMembers(data); err != nil {
77			return ReleasePlanInput{}, err
78		}
79		dec := json.NewDecoder(bytes.NewReader(data))
80		dec.UseNumber()
81		var doc map[string]any
82		if err := dec.Decode(&doc); err != nil {
83			return ReleasePlanInput{}, fmt.Errorf("JSON 格式错误: %w", err)
84		}
85		if dec.More() {
86			return ReleasePlanInput{}, errors.New("JSON 格式错误: 文档包含多余内容")
87		}
88		return buildReleaseInput(doc)
89	}
90	
91	// duplicateMemberError reports a JSON object whose member name appears more
92	// than once. Path is a JSONPath-style location: "$" for the document root,
93	// "$.clusters[1]" for a cluster, "$.clusters[0].tags" for a tag object,
94	// "$.include[2]" / "$.exclude[1]" for a condition, and "$.foo.bar[0]" for
95	// objects nested inside unknown fields.
96	type duplicateMemberError struct {
97		field string
98		path  string
99	}
100	
101	func (e *duplicateMemberError) Error() string {
102		return fmt.Sprintf("JSON 对象存在重复成员: 字段 %q 重复出现于 %s", e.field, e.path)
103	}
104	
105	// checkDuplicateMembers walks every JSON object in data and rejects objects
106	// with duplicate member names. Names are compared after JSON decoding, so
107	// "env" and "env" are the same name while "env" and "ENV", or
108	// " env" and "env", are different. The first duplicate encountered in file
109	// order is reported: the walk is depth-first in document order, so the
110	// second occurrence that appears earliest wins, regardless of value type.
111	func checkDuplicateMembers(data []byte) error {
112		dec := json.NewDecoder(bytes.NewReader(data))
113		// Numbers are only walked past, never interpreted: UseNumber keeps legal
114		// JSON numbers beyond float64 range (e.g. 1e400) from being turned into an
115		// unmarshal-overflow error here. Whether a number is acceptable for a given
116		// field is decided later by business validation.
117		dec.UseNumber()
118		if err := walkJSONValue(dec, "$"); err != nil {
119			return err
120		}
121		if _, err := dec.Token(); err != io.EOF {
122			if err == nil {
123				return errors.New("JSON 格式错误: 文档包含多余内容")
124			}
125			return fmt.Errorf("JSON 格式错误: %w", err)
126		}
127		return nil
128	}
129	
130	// walkJSONValue reads one complete JSON value whose first token has not been
131	// consumed yet.
132	func walkJSONValue(dec *json.Decoder, path string) error {
133		tok, err := dec.Token()
134		if err != nil {
135			if err == io.EOF {
136				return errors.New("JSON 格式错误: 文档为空")
137			}
138			return fmt.Errorf("JSON 格式错误: %w", err)
139		}
140		return walkJSONValueToken(dec, path, tok)
141	}
142	
143	// walkJSONValueToken reads the remainder of a value given its first token.
144	func walkJSONValueToken(dec *json.Decoder, path string, tok json.Token) error {
145		if d, ok := tok.(json.Delim); ok {
146			switch d {
147			case '{':
148				return walkJSONObject(dec, path)
149			case '[':
150				return walkJSONArray(dec, path)
151			default:
152				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
153			}
154		}
155		return nil // scalar value (string, number, bool, null)
156	}
157	
158	func walkJSONObject(dec *json.Decoder, path string) error {
159		seen := make(map[string]struct{})
160		for {
161			tok, err := dec.Token()
162			if err != nil {
163				if err == io.EOF {
164					return errors.New("JSON 格式错误: 对象未闭合")
165				}
166				return fmt.Errorf("JSON 格式错误: %w", err)
167			}
168			if d, ok := tok.(json.Delim); ok {
169				if d == '}' {
170					return nil
171				}
172				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
173			}
174			key, ok := tok.(string)
175			if !ok {
176				return errors.New("JSON 格式错误: 对象成员名必须是字符串")
177			}
178			if _, dup := seen[key]; dup {
179				return &duplicateMemberError{field: key, path: path}
180			}
181			seen[key] = struct{}{}
182			vtok, err := dec.Token()
183			if err != nil {
184				if err == io.EOF {
185					return errors.New("JSON 格式错误: 缺少成员值")
186				}
187				return fmt.Errorf("JSON 格式错误: %w", err)
188			}
189			if err := walkJSONValueToken(dec, path+"."+key, vtok); err != nil {
190				return err
191			}
192		}
193	}
194	
195	func walkJSONArray(dec *json.Decoder, path string) error {
196		for i := 0; ; i++ {
197			tok, err := dec.Token()
198			if err != nil {
199				if err == io.EOF {
200					return errors.New("JSON 格式错误: 数组未闭合")
201				}
202				return fmt.Errorf("JSON 格式错误: %w", err)
203			}
204			if d, ok := tok.(json.Delim); ok && d == ']' {
205				return nil
206			}
207			if err := walkJSONValueToken(dec, fmt.Sprintf("%s[%d]", path, i), tok); err != nil {
208				return err
209			}
210		}
211	}
212	
213	func buildReleaseInput(doc map[string]any) (ReleasePlanInput, error) {
214		app, err := requiredString(doc, "app")
215		if err != nil {
216			return ReleasePlanInput{}, err
217		}
218		revision, err := requiredString(doc, "revision")
219		if err != nil {
220			return ReleasePlanInput{}, err
221		}
222		image, err := requiredString(doc, "image")
223		if err != nil {
224			return ReleasePlanInput{}, err
225		}
226		batchSize, err := positiveInt(doc, "batchSize")
227		if err != nil {
228			return ReleasePlanInput{}, err
229		}
230		spreadBy, err := optionalSpreadBy(doc)
231		if err != nil {
232			return ReleasePlanInput{}, err
233		}
234		clusters, err := parseClusters(doc["clusters"])
235		if err != nil {
236			return ReleasePlanInput{}, err
237		}
238		include, err := parseConditions(doc["include"], "include")
239		if err != nil {
240			return ReleasePlanInput{}, err
241		}
242		exclude, err := parseConditions(doc["exclude"], "exclude")
243		if err != nil {
244			return ReleasePlanInput{}, err
245		}
246	
247		return ReleasePlanInput{
248			App:       app,
249			Revision:  revision,
250			Image:     image,
251			BatchSize: batchSize,
252			Clusters:  clusters,
253			Include:   include,
254			Exclude:   exclude,
255			SpreadBy:  spreadBy,
256		}, nil
257	}
258	
259	// optionalSpreadBy reads the optional "spreadBy" field: absent or an empty
260	// string disables fault-domain spreading; a non-string value or a string of
261	// only whitespace is rejected. The tag key is used exactly as written.
262	func optionalSpreadBy(doc map[string]any) (string, error) {
263		v, ok := doc["spreadBy"]
264		if !ok {
265			return "", nil
266		}
267		s, ok := v.(string)
268		if !ok {
269			return "", fmt.Errorf("字段 %q 必须是字符串", "spreadBy")
270		}
271		if err := checkSpreadBy(s); err != nil {
272			return "", err
273		}
274		return s, nil
275	}
276	
277	// checkSpreadBy rejects a spreadBy value that is neither empty nor a usable
278	// tag key: a string of only whitespace can never match a valid tag key.
279	func checkSpreadBy(s string) error {
280		if s != "" && strings.TrimSpace(s) == "" {
281			return fmt.Errorf("字段 %q 不能只含空白", "spreadBy")
282		}
283		return nil
284	}
285	
286	// ValidateReleaseInput checks that a release configuration is well-formed:
287	// app/revision/image are non-empty, batchSize is a positive integer, spreadBy
288	// is empty or a usable tag key (not whitespace-only), cluster
289	// IDs are unique across every candidate (including disabled and filtered-out
290	// clusters), and tag/condition keys are non-empty. Errors name the field and
291	// the position in its list; within a cluster the ID is checked before its
292	// tags, and tag keys are examined in ascending order so repeated calls report
293	// the same error. The input is never mutated. MakeReleasePlan calls this
294	// automatically; library callers may use it to validate without planning.
295	func ValidateReleaseInput(in ReleasePlanInput) error {
296		if strings.TrimSpace(in.App) == "" {
297			return errors.New(`字段 "app" 不能为空或只含空白`)
298		}
299		if strings.TrimSpace(in.Revision) == "" {
300			return errors.New(`字段 "revision" 不能为空或只含空白`)
301		}
302		if strings.TrimSpace(in.Image) == "" {
303			return errors.New(`字段 "image" 不能为空或只含空白`)
304		}
305		if in.BatchSize <= 0 {
306			return errors.New(`字段 "batchSize" 必须是正整数`)
307		}
308		if err := checkSpreadBy(in.SpreadBy); err != nil {
309			return err
310		}
311		seen := make(map[string]struct{}, len(in.Clusters))
312		for i, c := range in.Clusters {
313			if strings.TrimSpace(c.ID) == "" {
314				return fmt.Errorf("clusters[%d]: 字段 %q 不能为空或只含空白", i, "id")
315			}
316			if _, dup := seen[c.ID]; dup {
317				return fmt.Errorf("clusters[%d]: 重复的集群标识 %q", i, c.ID)
318			}
319			seen[c.ID] = struct{}{}
320			if err := validateTagKeys(i, c.Tags); err != nil {
321				return err
322			}
323		}
324		if err := validateConditionKeys("include", in.Include); err != nil {
325			return err
326		}
327		if err := validateConditionKeys("exclude", in.Exclude); err != nil {
328			return err
329		}
330		return nil
331	}
332	
333	// validateTagKeys applies the shared label-key rule to one cluster's tags,
334	// reporting the cluster's position in the candidate list.
335	func validateTagKeys(clusterIndex int, tags map[string]string) error {
336		if hasEmptyLabelKey(tags) {
337			return fmt.Errorf("clusters[%d] 的标签键不能为空", clusterIndex)
338		}
339		return nil
340	}
341	
342	// validateConditionKeys applies the shared condition rules to every condition
343	// in original order, so the first invalid condition is reported.
344	func validateConditionKeys(field string, conds []LabelCondition) error {
345		for i, cond := range conds {
346			if err := validateCondition(field, i, cond); err != nil {
347				return err
348			}
349		}
350		return nil
351	}
352	
353	func requiredString(doc map[string]any, field string) (string, error) {
354		v, ok := doc[field]
355		if !ok {
356			return "", fmt.Errorf("缺少必需字段 %q", field)
357		}
358		s, ok := v.(string)
359		if !ok {
360			return "", fmt.Errorf("字段 %q 必须是字符串", field)
361		}
362		if strings.TrimSpace(s) == "" {
363			return "", fmt.Errorf("字段 %q 不能为空或只含空白", field)
364		}
365		return s, nil
366	}
367	
368	func positiveInt(doc map[string]any, field string) (int, error) {
369		v, ok := doc[field]
370		if !ok {
371			return 0, fmt.Errorf("缺少必需字段 %q", field)
372		}
373		n, ok := v.(json.Number)
374		if !ok {
375			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
376		}
377		i, err := n.Int64()
378		if err != nil || i <= 0 {
379			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
380		}
381		return int(i), nil
382	}
383	
384	func parseClusters(v any) ([]Cluster, error) {
385		if v == nil {
386			return nil, errors.New("缺少必需字段 \"clusters\"")
387		}
388		raw, ok := v.([]any)
389		if !ok {
390			return nil, errors.New("字段 \"clusters\" 必须是数组")
391		}
392		clusters := make([]Cluster, 0, len(raw))
393		seen := make(map[string]bool)
394		for i, item := range raw {
395			obj, ok := item.(map[string]any)
396			if !ok {
397				return nil, fmt.Errorf("clusters[%d] 必须是对象", i)
398			}
399			id, err := requiredString(obj, "id")
400			if err != nil {
401				return nil, fmt.Errorf("clusters[%d]: %w", i, err)
402			}
403			if seen[id] {
404				return nil, fmt.Errorf("clusters[%d]: 重复的集群标识 %q", i, id)
405			}
406			seen[id] = true
407	
408			disabled := false
409			if dv, present := obj["disabled"]; present {
410				b, ok := dv.(bool)
411				if !ok {
412					return nil, fmt.Errorf("集群 %q 的 \"disabled\" 必须是布尔值", id)
413				}
414				disabled = b
415			}
416	
417			tags := map[string]string{}
418			if tv, present := obj["tags"]; present {
419				tm, ok := tv.(map[string]any)
420				if !ok {
421					return nil, fmt.Errorf("集群 %q 的 \"tags\" 必须是对象", id)
422				}
423				tags, err = labelsFromJSON(tm,
424					func(string) error { return fmt.Errorf("集群 %q 的标签键不能为空", id) },
425					func(k string) error { return fmt.Errorf("集群 %q 的标签 %q 值必须是字符串", id, k) },
426				)
427				if err != nil {
428					return nil, err
429				}
430			}
431	
432			clusters = append(clusters, Cluster{ID: id, Disabled: disabled, Tags: tags})
433		}
434		return clusters, nil
435	}
436	
437	func parseConditions(v any, field string) ([]LabelCondition, error) {
438		if v == nil {
439			return []LabelCondition{}, nil
440		}
441		raw, ok := v.([]any)
442		if !ok {
443			return nil, fmt.Errorf("字段 %q 必须是条件数组", field)
444		}
445		conds := make([]LabelCondition, 0, len(raw))
446		for i, item := range raw {
447			obj, ok := item.(map[string]any)
448			if !ok {
449				return nil, fmt.Errorf("%s[%d] 必须是对象", field, i)
450			}
451			cond, err := labelsFromJSON(obj,
452				func(string) error { return fmt.Errorf("%s[%d] 的标签键不能为空", field, i) },
453				func(k string) error { return fmt.Errorf("%s[%d] 的标签 %q 值必须是字符串", field, i, k) },
454			)
455			if err != nil {
456				return nil, err
457			}
458			if err := validateCondition(field, i, cond); err != nil {
459				return nil, err
460			}
461			conds = append(conds, cond)
462		}
463		return conds, nil
464	}
465	
466	// MakeReleasePlan selects available clusters, orders them by ID, and splits
467	// them into batches. When SpreadBy names a tag, each batch holds at most one
468	// cluster per value of that tag (its fault domain) and every selected cluster
469	// must carry the tag. It validates the input first and never mutates it.
470	func MakeReleasePlan(in ReleasePlanInput) (ReleasePlan, error) {
471		if err := ValidateReleaseInput(in); err != nil {
472			return ReleasePlan{}, err
473		}
474		if len(in.Clusters) == 0 {
475			return ReleasePlan{}, errors.New("没有可发布的集群：未提供候选集群")
476		}
477	
478		selected := []string{}
479		excluded := []ExcludedCluster{}
480		for _, c := range in.Clusters {
481			switch {
482			case c.Disabled:
483				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonDisabled})
484			case matchesAny(c.Tags, in.Exclude):
485				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonExcludeMatched})
486			case len(in.Include) > 0 && !matchesAny(c.Tags, in.Include):
487				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonIncludeNotMatched})
488			default:
489				selected = append(selected, c.ID)
490			}
491		}
492	
493		sort.Strings(selected)
494		sort.Slice(excluded, func(i, j int) bool { return excluded[i].ID < excluded[j].ID })
495	
496		if len(selected) == 0 {
497			var b strings.Builder
498			b.WriteString("没有符合规则的可用集群，各候选集群未入选原因：")
499			for _, e := range excluded {
500				b.WriteString("\n  ")
501				b.WriteString(e.ID)
502				b.WriteString("：")
503				b.WriteString(e.Reason)
504			}
505			return ReleasePlan{}, errors.New(b.String())
506		}
507	
508		var batches []Batch
509		if in.SpreadBy == "" {
510			batches = chunkBatches(selected, in.BatchSize)
511		} else {
512			domains, err := faultDomains(in.Clusters, selected, in.SpreadBy)
513			if err != nil {
514				return ReleasePlan{}, err
515			}
516			batches = spreadBatches(selected, domains, in.BatchSize)
517		}
518	
519		return ReleasePlan{
520			App:      AppInfo{Name: in.App, Revision: in.Revision, Image: in.Image},
521			Batches:  batches,
522			Excluded: excluded,
523		}, nil
524	}
525	
526	// chunkBatches splits the ascending IDs into batches of at most batchSize.
527	func chunkBatches(selected []string, batchSize int) []Batch {
528		batches := []Batch{}
529		for i := 0; i < len(selected); i += batchSize {
530			end := i + batchSize
531			if end > len(selected) {
532				end = len(selected)
533			}
534			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: selected[i:end]})
535		}
536		return batches
537	}
538	
539	// faultDomains maps every selected cluster ID to the exact value of its
540	// spreadBy tag. A selected cluster missing the tag fails the whole plan;
541	// selected is ascending, so the smallest such ID is reported. An empty
542	// string tag value is a valid fault domain, distinct from a missing tag.
543	func faultDomains(clusters []Cluster, selected []string, spreadBy string) (map[string]string, error) {
544		tagsByID := make(map[string]map[string]string, len(clusters))
545		for _, c := range clusters {
546			tagsByID[c.ID] = c.Tags
547		}
548		domains := make(map[string]string, len(selected))
549		for _, id := range selected {
550			v, ok := tagsByID[id][spreadBy]
551			if !ok {
552				return nil, fmt.Errorf("集群 %q 缺少故障域标签 %q", id, spreadBy)
553			}
554			domains[id] = v
555		}
556		return domains, nil
557	}
558	
559	// spreadBatches packs the ascending IDs into batches of at most batchSize
560	// with at most one cluster per fault domain in each batch. Each batch takes
561	// the smallest still-unscheduled IDs whose domains do not conflict with the
562	// batch; conflicting clusters are deferred to later batches, so a batch may
563	// be short only when no non-conflicting cluster remains. Every ID appears in
564	// exactly one batch and IDs stay ascending within a batch.
565	func spreadBatches(selected []string, domains map[string]string, batchSize int) []Batch {
566		remaining := append([]string(nil), selected...)
567		batches := []Batch{}
568		for len(remaining) > 0 {
569			// The map never holds more entries than there are remaining clusters,
570			// so size it by them — never by batchSize, which is only an upper
571			// bound and may be a huge legal value (e.g. 1e9 meaning "no limit").
572			used := make(map[string]struct{}, min(batchSize, len(remaining)))
573			batch := []string{}
574			deferred := []string{}
575			for _, id := range remaining {
576				d := domains[id]
577				if _, conflict := used[d]; len(batch) < batchSize && !conflict {
578					used[d] = struct{}{}
579					batch = append(batch, id)
580				} else {
581					deferred = append(deferred, id)
582				}
583			}
584			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: batch})
585			remaining = deferred
586		}
587		return batches
588	}
589	
590	func matchesAny(tags map[string]string, conditions []LabelCondition) bool {
591		for _, cond := range conditions {
592			if matchesAll(tags, cond) {
593				return true
594			}
595		}
596		return false
597	}
598	
599	func matchesAll(tags map[string]string, cond LabelCondition) bool {
600		for k, v := range cond {
601			tv, ok := tags[k]
602			if !ok || tv != v {
603				return false
604			}
605		}
606		return true
607	}
608

