3	import (
4		"strings"
5		"testing"
6	)
7	
8	// A huge but legal batchSize (users set e.g. 1000000000 to mean "capacity is
9	// no constraint") must not make planning allocate memory proportional to that
10	// number: resource use depends on the actual cluster count. The spreadBy
11	// rules still apply unchanged — a huge capacity does not merge conflicting
12	// fault domains into one batch.
13	func TestPlan_HugeBatchSizeWithSpreadBy(t *testing.T) {
14		in := ReleasePlanInput{
15			App: "app", Revision: "r1", Image: "img",
16			BatchSize: 1000000000,
17			SpreadBy:  "zone",
18			Clusters: []Cluster{
19				{ID: "a", Tags: map[string]string{"zone": "east"}},
20				{ID: "b", Tags: map[string]string{"zone": "east"}},
21				{ID: "c", Tags: map[string]string{"zone": "west"}},
22			},
23		}
24		plan, err := MakeReleasePlan(in)
25		if err != nil {
